//! Corpus of old/new SREC pairs.
//!
//! Each subdirectory of [`PAIRS_DIR`] that contains `old.srec` and `new.srec`
//! is one pair, in directory-name order. Drop a real pair in a new
//! subdirectory and run `crab-cage delta sync-cases`. The synthetic pairs are
//! generated by [`write_synthetic`]; the compiled pairs are produced by
//! `corpus/firmware/build.sh`.

use std::fs;
use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::error::{err, Result};

use super::encode::{self, FamilyParams};
use super::image::{Image, Region};
use super::srec;

pub const PAIRS_DIR: &str = "corpus/pairs";

#[derive(Clone, Debug)]
pub struct Pair {
    pub name: String,
    pub old: Image,
    pub new: Image,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct PairMeasure {
    pub name: String,
    pub new_bytes: u64,
    pub span: u64,
    pub add_only: u64,
    pub strategy_a: u64,
    pub strategy_b: u64,
    pub reference: u64,
    pub optimal: u64,
    pub cross_sector: u64,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Measurement {
    pub pairs: Vec<PairMeasure>,
    pub family: FamilyParams,
    pub family_bytes: Vec<u64>,
    pub family_total: u64,
}

pub fn load_pairs(dir: &Path) -> Result<Vec<Pair>> {
    let mut names = Vec::new();
    let entries = fs::read_dir(dir).map_err(|error| err(format!("{}: {error}", dir.display())))?;
    for entry in entries {
        let entry = entry.map_err(|error| err(error.to_string()))?;
        if !entry
            .file_type()
            .map_err(|error| err(error.to_string()))?
            .is_dir()
        {
            continue;
        }
        let path = entry.path();
        if path.join("old.srec").is_file() && path.join("new.srec").is_file() {
            names.push(path);
        }
    }
    names.sort();
    let mut pairs = Vec::new();
    for path in names {
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("pair")
            .to_string();
        let old = Image::from_regions(srec::parse(&read(&path.join("old.srec"))?)?)?;
        let new = Image::from_regions(srec::parse(&read(&path.join("new.srec"))?)?)?;
        pairs.push(Pair { name, old, new });
    }
    if pairs.is_empty() {
        return Err(err(format!(
            "{} has no old.srec/new.srec pairs",
            dir.display()
        )));
    }
    Ok(pairs)
}

pub fn sync_cases(corpus: &Path, nugget: &Path) -> Result<()> {
    let pairs = load_pairs(corpus)?;
    let cases = nugget.join("cases");
    fs::create_dir_all(&cases)?;
    for pair in &pairs {
        let text = super::kernel::case_input(&pair.name, &pair.old, &pair.new)?;
        fs::write(cases.join(format!("{}.in", pair.name)), text)?;
    }
    Ok(())
}

pub fn measure(pairs: &[Pair]) -> Result<Measurement> {
    let mut rows = Vec::new();
    for pair in pairs {
        let add_only = encode::encode_add_only(&pair.old, &pair.new)?;
        let strategy_a = encode::encode_strategy_a(&pair.old, &pair.new)?;
        let strategy_b = encode::encode_strategy_b_local(&pair.old, &pair.new)?;
        let reference = encode::encode_reference(&pair.old, &pair.new)?;
        let optimal = encode::encode_optimal_file(&pair.old, &pair.new)?;
        let cross = encode::proposal_cross_sector(&pair.old, &pair.new)?;
        rows.push(PairMeasure {
            name: pair.name.clone(),
            new_bytes: pair.new.real_bytes(),
            span: span_of(&pair.old, &pair.new),
            add_only: add_only.bytes.len() as u64,
            strategy_a: strategy_a.bytes.len() as u64,
            strategy_b: strategy_b.bytes.len() as u64,
            reference: reference.bytes.len() as u64,
            optimal: optimal.bytes.len() as u64,
            cross_sector: cross,
        });
    }
    let images: Vec<(Image, Image)> = pairs
        .iter()
        .map(|pair| (pair.old.clone(), pair.new.clone()))
        .collect();
    let (family, family_total) = encode::search_family(&images)?;
    let mut family_bytes = Vec::new();
    for pair in pairs {
        let planned = encode::encode_family(&pair.old, &pair.new, &family)?;
        family_bytes.push(planned.bytes.len() as u64);
    }
    Ok(Measurement {
        pairs: rows,
        family,
        family_bytes,
        family_total,
    })
}

pub fn write_synthetic(dir: &Path) -> Result<()> {
    for (name, old, new, about) in synthetic_pairs() {
        let path = dir.join(name);
        fs::create_dir_all(&path)?;
        fs::write(path.join("old.srec"), srec::write(&old))?;
        fs::write(path.join("new.srec"), srec::write(&new))?;
        fs::write(path.join("README.md"), about)?;
    }
    Ok(())
}

pub fn synthetic_pairs() -> Vec<(String, Vec<Region>, Vec<Region>, String)> {
    let mut out = Vec::new();
    out.push(shift_inside());
    out.push(scattered());
    out.push(move_earlier());
    out.push(unaligned());
    out
}

fn shift_inside() -> (String, Vec<Region>, Vec<Region>, String) {
    let mut old = vec![0u8; 128];
    let mut i = 0;
    while i < 40 {
        old[i] = 0x30 + (i as u8);
        old[40 + i] = 0x80;
        i += 1;
    }
    let mut newb = vec![0u8; 128];
    let mut i = 0;
    while i < 40 {
        newb[i] = 0x80;
        newb[40 + i] = 0x30 + (i as u8);
        i += 1;
    }
    (
        "05-shift-inside".to_string(),
        vec![Region {
            address: 0x0800_0000,
            data: old,
        }],
        vec![Region {
            address: 0x0800_0000,
            data: newb,
        }],
        "\
Synthetic, generated by `delta::corpus::synthetic_pairs` (not a compiled image).\n\
\n\
128 real bytes at 0x08000000. The old image holds a 40-byte ramp at offset 0\n\
and 40 bytes of 0x80 after it. The new image swaps those two blocks. A\n\
sector-local LOAD can copy each block; an ADD-only encoding pays for both.\n"
            .to_string(),
    )
}

fn scattered() -> (String, Vec<Region>, Vec<Region>, String) {
    let mut old = vec![0u8; 512];
    let mut i = 0;
    while i < old.len() {
        old[i] = ((i * 17) ^ 0x3C) as u8;
        i += 1;
    }
    let mut newb = old.clone();
    let mut i = 0;
    while i < newb.len() {
        newb[i] ^= 0xFF;
        i += 17;
    }
    (
        "06-scattered".to_string(),
        vec![Region {
            address: 0x0800_0000,
            data: old,
        }],
        vec![Region {
            address: 0x0800_0000,
            data: newb,
        }],
        "\
Synthetic, generated by `delta::corpus::synthetic_pairs`.\n\
\n\
512 real bytes at 0x08000000. The new image flips every 17th byte\n\
(`byte ^= 0xFF`). The surrounding bytes still match, which is the case\n\
strategy A (one LOAD, then small ADDs) is built for.\n"
            .to_string(),
    )
}

fn move_earlier() -> (String, Vec<Region>, Vec<Region>, String) {
    let mut block = vec![0u8; 180];
    let mut i = 0;
    while i < block.len() {
        block[i] = ((i * 13 + 7) & 0xFF) as u8;
        if block[i] == 0xFF {
            block[i] = 0x7E;
        }
        i += 1;
    }
    let stub = vec![0x11u8; 32];
    let mut old = Vec::new();
    old.push(Region {
        address: 0x0800_0000,
        data: stub.clone(),
    });
    old.push(Region {
        address: 0x0800_0800,
        data: block.clone(),
    });
    let mut replacement = vec![0x22u8; 32];
    replacement[0] = 0x23;
    let newb = vec![
        Region {
            address: 0x0800_0000,
            data: block,
        },
        Region {
            address: 0x0800_0800,
            data: replacement,
        },
    ];
    (
        "07-move-earlier".to_string(),
        old,
        newb,
        "\
Synthetic, generated by `delta::corpus::synthetic_pairs`.\n\
\n\
The 180-byte block lives at 0x08000800 in the old image and at 0x08000000\n\
in the new one. v0.03 can only LOAD inside the sector being stored, so the\n\
block is literals. A cross-sector LOAD could read it from the later sector,\n\
which has not been erased yet because sectors run in ascending order.\n"
            .to_string(),
    )
}

fn unaligned() -> (String, Vec<Region>, Vec<Region>, String) {
    let mut old = vec![0x5Au8; 48];
    old[10] = 0x10;
    let mut newb = old.clone();
    newb[10] = 0x11;
    (
        "08-unaligned".to_string(),
        vec![Region {
            address: 0x0800_0040,
            data: old,
        }],
        vec![Region {
            address: 0x0800_0040,
            data: newb,
        }],
        "\
Synthetic, generated by `delta::corpus::synthetic_pairs`.\n\
\n\
48 real bytes at 0x08000040, which is not 2 KB aligned. The sector base in\n\
the delta is 0x08000000 and the commands use the intra-sector offset 0x40.\n\
One payload byte changes from 0x10 to 0x11.\n"
            .to_string(),
    )
}

fn span_of(old: &Image, new: &Image) -> u64 {
    let bases = [old.base_addr(), new.base_addr()];
    let ends = [old.end_addr(), new.end_addr()];
    match (
        bases.into_iter().flatten().min(),
        ends.into_iter().flatten().max(),
    ) {
        (Some(lo), Some(hi)) => u64::from(hi - lo),
        _ => 0,
    }
}

fn read(path: &Path) -> Result<String> {
    fs::read_to_string(path)
        .map_err(|error| err(format!("{}: {error}", path.display())))
        .map(|text| text.replace("\r\n", "\n"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn synthetic_pairs_round_trip_and_optimal_is_smallest() {
        let built = synthetic_pairs();
        let mut pairs = Vec::new();
        for (name, old, new, _) in built {
            let old_text = srec::write(&old);
            let new_text = srec::write(&new);
            let old = Image::from_regions(srec::parse(&old_text).unwrap()).unwrap();
            let new = Image::from_regions(srec::parse(&new_text).unwrap()).unwrap();
            pairs.push(Pair { name, old, new });
        }
        let measured = measure(&pairs).unwrap();
        assert_eq!(measured.pairs.len(), 4);
        let mut saw_cross_win = false;
        for (row, family) in measured.pairs.iter().zip(&measured.family_bytes) {
            assert!(
                row.optimal <= row.add_only,
                "{} optimal {} add {}",
                row.name,
                row.optimal,
                row.add_only
            );
            assert!(
                row.optimal <= row.strategy_a,
                "{} optimal {} A {}",
                row.name,
                row.optimal,
                row.strategy_a
            );
            assert!(
                row.optimal <= row.strategy_b,
                "{} optimal {} B {}",
                row.name,
                row.optimal,
                row.strategy_b
            );
            assert!(
                row.optimal <= row.reference,
                "{} optimal {} ref {}",
                row.name,
                row.optimal,
                row.reference
            );
            assert!(
                row.optimal <= *family,
                "{} optimal {} family {}",
                row.name,
                row.optimal,
                family
            );
            if row.cross_sector < row.optimal {
                saw_cross_win = true;
            }
        }
        assert!(saw_cross_win, "moving a block earlier should beat v0.03");
        assert_eq!(
            measured.family_total,
            measured.family_bytes.iter().sum::<u64>()
        );
    }

    #[test]
    fn the_committed_report_matches_a_fresh_measure() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
        let pairs = load_pairs(&root.join(PAIRS_DIR)).unwrap();
        let measured = measure(&pairs).unwrap();
        let text = fs::read_to_string(root.join("corpus/results.json")).unwrap();
        let locked: Measurement = serde_json::from_str(&text).unwrap();
        assert_eq!(measured, locked);
    }
}
